//! Finite groups as permutation groups: every group is generated by permutations
//! of 0..n (shown 1-based, as Galileo's permutations are), its elements are
//! enumerated on demand. A group prints as the Galileo call that rebuilds it.

use std::collections::HashMap;

pub type Perm = Vec<u16>;

/// the largest group that is enumerated
pub const MAX_ORDER: usize = 500_000;

#[derive(Clone, Debug)]
pub struct Group {
    /// the Galileo text that rebuilds it, such as sym(4) or group([2, 1, 3], [2, 3, 1])
    pub name: String,
    pub degree: usize,
    pub gens: Vec<Perm>,
    elems: Vec<Perm>,
    index: HashMap<Perm, usize>,
    /// for a matrix group: how its matrices act on the vectors (the points)
    pub mats: Option<std::rc::Rc<crate::matgroup::Action>>,
}

impl PartialEq for Group {
    fn eq(&self, o: &Group) -> bool {
        self.degree == o.degree && self.elems.len() == o.elems.len() && self.elems == o.elems
    }
}

pub fn identity(n: usize) -> Perm {
    (0..n as u16).collect()
}

/// p after q: (p q)(i) = p(q(i))
pub fn mul(p: &Perm, q: &Perm) -> Perm {
    q.iter().map(|&i| p[i as usize]).collect()
}

pub fn inv(p: &Perm) -> Perm {
    let mut r = vec![0u16; p.len()];
    for (i, &k) in p.iter().enumerate() {
        r[k as usize] = i as u16;
    }
    r
}

pub fn order_of(p: &Perm) -> usize {
    let id = identity(p.len());
    let mut q = p.clone();
    let mut k = 1;
    while q != id {
        q = mul(p, &q);
        k += 1;
    }
    k
}

/// "[2, 3, 1]": the 1-based list, Galileo's form of a permutation
pub fn show_perm(p: &Perm) -> String {
    format!(
        "[{}]",
        p.iter()
            .map(|k| (k + 1).to_string())
            .collect::<Vec<_>>()
            .join(", ")
    )
}

/// "(1 2 3)(4 5)", "()" for the identity
pub fn cycles(p: &Perm) -> String {
    let mut seen = vec![false; p.len()];
    let mut out = String::new();
    for s in 0..p.len() {
        if seen[s] || p[s] as usize == s {
            continue;
        }
        let mut c = vec![];
        let mut i = s;
        while !seen[i] {
            seen[i] = true;
            c.push((i + 1).to_string());
            i = p[i] as usize;
        }
        out.push_str(&format!("({})", c.join(" ")));
    }
    if out.is_empty() { "()".into() } else { out }
}

fn gcd(a: usize, b: usize) -> usize {
    if b == 0 { a } else { gcd(b, a % b) }
}

impl Group {
    /// the group generated by gens (all of degree n); Err when too large
    pub fn new(name: impl Into<String>, n: usize, gens: Vec<Perm>) -> Result<Group, String> {
        let id = identity(n);
        let gens: Vec<Perm> = gens.into_iter().filter(|g| *g != id).collect();
        let mut elems = vec![id.clone()];
        let mut index = HashMap::new();
        index.insert(id, 0);
        let mut k = 0;
        while k < elems.len() {
            for g in &gens {
                let h = mul(g, &elems[k]);
                if !index.contains_key(&h) {
                    if elems.len() >= MAX_ORDER {
                        return Err(format!(
                            "the group has more than {} elements, too many to list",
                            MAX_ORDER
                        ));
                    }
                    index.insert(h.clone(), elems.len());
                    elems.push(h);
                }
            }
            k += 1;
        }
        // sorted, identity first
        elems.sort();
        let index = elems
            .iter()
            .cloned()
            .enumerate()
            .map(|(i, e)| (e, i))
            .collect();
        Ok(Group {
            name: name.into(),
            degree: n,
            gens,
            elems,
            index,
            mats: None,
        })
    }

    /// a group built from generators, named by them
    pub fn from_gens(n: usize, gens: Vec<Perm>) -> Result<Group, String> {
        let name = Self::gens_name(&gens, n);
        Group::new(name, n, gens)
    }

    fn gens_name(gens: &[Perm], n: usize) -> String {
        let id = identity(n);
        let gs: Vec<String> = gens.iter().filter(|g| **g != id).map(show_perm).collect();
        if gs.is_empty() {
            format!("group({})", show_perm(&id))
        } else {
            format!("group({})", gs.join(", "))
        }
    }

    pub fn order(&self) -> usize {
        self.elems.len()
    }

    pub fn elements(&self) -> &[Perm] {
        &self.elems
    }

    pub fn contains(&self, p: &Perm) -> bool {
        self.index.contains_key(p)
    }

    pub fn identity(&self) -> Perm {
        identity(self.degree)
    }

    pub fn is_abelian(&self) -> bool {
        self.gens
            .iter()
            .all(|a| self.gens.iter().all(|b| mul(a, b) == mul(b, a)))
    }

    pub fn is_subgroup_of(&self, g: &Group) -> bool {
        self.degree == g.degree && self.gens.iter().all(|h| g.contains(h))
    }

    /// the subgroup generated by these elements
    pub fn sub(&self, gens: Vec<Perm>) -> Result<Group, String> {
        let mut h = Group::from_gens(self.degree, gens)?;
        if let Some(a) = &self.mats {
            h.name = a.gens_name(&h.gens);
            h.mats = Some(a.clone());
        }
        Ok(h)
    }

    pub fn center(&self) -> Result<Group, String> {
        let z: Vec<Perm> = self
            .elems
            .iter()
            .filter(|z| self.gens.iter().all(|g| mul(g, z) == mul(z, g)))
            .cloned()
            .collect();
        self.sub(z)
    }

    /// conjugacy classes, each sorted, the identity's first
    pub fn classes(&self) -> Vec<Vec<Perm>> {
        let mut seen = vec![false; self.order()];
        let mut out = vec![];
        for (i, x) in self.elems.iter().enumerate() {
            if seen[i] {
                continue;
            }
            // the orbit of x under conjugation by generators
            let mut cls = vec![x.clone()];
            seen[i] = true;
            let mut k = 0;
            while k < cls.len() {
                for g in &self.gens {
                    let y = mul(&mul(g, &cls[k]), &inv(g));
                    let j = self.index[&y];
                    if !seen[j] {
                        seen[j] = true;
                        cls.push(y);
                    }
                }
                k += 1;
            }
            cls.sort();
            out.push(cls);
        }
        out
    }

    pub fn is_normal(&self, h: &Group) -> bool {
        self.gens.iter().all(|g| {
            let gi = inv(g);
            h.gens.iter().all(|x| h.contains(&mul(&mul(g, x), &gi)))
        })
    }

    /// left cosets g H, each sorted, H first
    pub fn cosets(&self, h: &Group) -> Vec<Vec<Perm>> {
        let mut seen = vec![false; self.order()];
        let mut out = vec![];
        for (i, g) in self.elems.iter().enumerate() {
            if seen[i] {
                continue;
            }
            let mut c: Vec<Perm> = h.elems.iter().map(|x| mul(g, x)).collect();
            c.sort();
            for x in &c {
                seen[self.index[x]] = true;
            }
            out.push(c);
        }
        out
    }

    /// G/N as a permutation group on the cosets of N
    pub fn quotient(&self, nsub: &Group) -> Result<Group, String> {
        let cos = self.cosets(nsub);
        let mut which = HashMap::new();
        for (k, c) in cos.iter().enumerate() {
            for x in c {
                which.insert(x.clone(), k as u16);
            }
        }
        let gens: Vec<Perm> = self
            .gens
            .iter()
            .map(|g| cos.iter().map(|c| which[&mul(g, &c[0])]).collect())
            .collect();
        Group::new(
            format!("quotient({}, {})", self.name, nsub.name),
            cos.len(),
            gens,
        )
    }

    /// the commutator (derived) subgroup [G, G]
    pub fn derived(&self) -> Result<Group, String> {
        // normal closure of the commutators of generators
        let mut c = vec![];
        for a in &self.gens {
            for b in &self.gens {
                c.push(mul(&mul(&inv(a), &inv(b)), &mul(a, b)));
            }
        }
        let mut h = self.sub(c.clone())?;
        loop {
            let mut more = h.gens.clone();
            let mut grew = false;
            for g in &self.gens {
                for x in &h.gens {
                    let y = mul(&mul(g, x), &inv(g));
                    if !h.contains(&y) {
                        more.push(y);
                        grew = true;
                    }
                }
            }
            if !grew {
                return Ok(h);
            }
            h = self.sub(more)?;
        }
    }

    /// G, G', G'', ... down to where it stops changing
    pub fn derived_series(&self) -> Result<Vec<Group>, String> {
        let mut s = vec![self.clone()];
        loop {
            let d = s.last().unwrap().derived()?;
            if d.order() == s.last().unwrap().order() {
                return Ok(s);
            }
            let done = d.order() == 1;
            s.push(d);
            if done {
                return Ok(s);
            }
        }
    }

    pub fn is_solvable(&self) -> Result<bool, String> {
        Ok(self.derived_series()?.last().unwrap().order() == 1)
    }

    /// no normal subgroups but 1 and G: checked on normal closures of class representatives
    pub fn is_simple(&self) -> Result<bool, String> {
        if self.order() == 1 {
            return Ok(false);
        }
        for cls in self.classes().iter().skip(1) {
            if self.normal_closure(&cls[0])?.order() < self.order() {
                return Ok(false);
            }
        }
        Ok(true)
    }

    pub fn normal_closure(&self, x: &Perm) -> Result<Group, String> {
        let cls = self
            .classes()
            .into_iter()
            .find(|c| c.contains(x))
            .unwrap_or_default();
        self.sub(cls)
    }

    /// [order, how many elements have it], by order
    pub fn order_counts(&self) -> Vec<(usize, usize)> {
        let mut m: std::collections::BTreeMap<usize, usize> = Default::default();
        for e in &self.elems {
            *m.entry(order_of(e)).or_default() += 1;
        }
        m.into_iter().collect()
    }

    /// a Sylow p-subgroup: grow a p-subgroup by elements of p-power order that normalize it
    pub fn sylow(&self, p: usize) -> Result<Group, String> {
        let mut pk = 1;
        let mut n = self.order();
        while n % p == 0 {
            n /= p;
            pk *= p;
        }
        let ppow = |k: usize| {
            let mut k = k;
            while k % p == 0 {
                k /= p;
            }
            k == 1
        };
        let mut h = self.sub(vec![])?;
        while h.order() < pk {
            // an element of p-power order outside h that normalizes h and keeps a p-group
            let mut grown = false;
            for x in &self.elems {
                if h.contains(x) || !ppow(order_of(x)) {
                    continue;
                }
                let xi = inv(x);
                if !h.gens.iter().all(|g| h.contains(&mul(&mul(x, g), &xi))) {
                    continue;
                }
                let mut gens = h.gens.clone();
                gens.push(x.clone());
                let k = self.sub(gens)?;
                if ppow(k.order()) {
                    h = k;
                    grown = true;
                    break;
                }
            }
            if !grown {
                return Err("sylow: could not grow the p-subgroup (this should not happen)".into());
            }
        }
        Ok(h)
    }

    /// the direct product G × H acting on the disjoint union of the points
    pub fn product(&self, h: &Group) -> Result<Group, String> {
        let (n, m) = (self.degree, h.degree);
        let lift_g = |g: &Perm| -> Perm {
            g.iter()
                .cloned()
                .chain((n..n + m).map(|i| i as u16))
                .collect()
        };
        let lift_h = |k: &Perm| -> Perm {
            (0..n as u16)
                .chain(k.iter().map(|&i| i + n as u16))
                .collect()
        };
        let gens: Vec<Perm> = self
            .gens
            .iter()
            .map(lift_g)
            .chain(h.gens.iter().map(lift_h))
            .collect();
        Group::new(format!("dprod({}, {})", self.name, h.name), n + m, gens)
    }

    /// Cayley table: entry (i, j) is the index (1-based) of e_i e_j
    pub fn table(&self) -> Vec<Vec<usize>> {
        self.elems
            .iter()
            .map(|a| {
                self.elems
                    .iter()
                    .map(|b| self.index[&mul(a, b)] + 1)
                    .collect()
            })
            .collect()
    }

    /// a short description for notes
    pub fn describe(&self) -> String {
        format!("{} has order {}", self.name, self.order())
    }
}

// ---------- the standard groups ----------

pub fn sym(n: usize) -> Result<Group, String> {
    let mut gens = vec![];
    if n >= 2 {
        let mut t = identity(n);
        t.swap(0, 1);
        gens.push(t);
    }
    if n >= 3 {
        gens.push((0..n).map(|i| ((i + 1) % n) as u16).collect());
    }
    Group::new(format!("sym({})", n), n.max(1), gens)
}

pub fn alt(n: usize) -> Result<Group, String> {
    // 3-cycles (1 2 k)
    let gens = (2..n)
        .map(|k| {
            let mut p = identity(n);
            p[0] = 1;
            p[1] = k as u16;
            p[k] = 0;
            p
        })
        .collect();
    Group::new(format!("alt({})", n), n.max(1), gens)
}

pub fn cyclic(n: usize) -> Result<Group, String> {
    Group::new(
        format!("cyclic({})", n),
        n.max(1),
        vec![(0..n).map(|i| ((i + 1) % n) as u16).collect()],
    )
}

/// the symmetries of a regular n-gon (order 2n)
pub fn dihedral(n: usize) -> Result<Group, String> {
    if n < 3 {
        return Err("dihedral(n): n from 3 (the symmetries of a regular n-gon)".into());
    }
    let r: Perm = (0..n).map(|i| ((i + 1) % n) as u16).collect();
    let s: Perm = (0..n).map(|i| ((n - i) % n) as u16).collect();
    Group::new(format!("dihedral({})", n), n, vec![r, s])
}

/// the units of Z/n under multiplication, acting on the residues 0..n-1
pub fn units(n: usize) -> Result<Group, String> {
    if n < 2 {
        return Err("units(n): n from 2".into());
    }
    let gens = (2..n)
        .filter(|&a| gcd(a, n) == 1)
        .map(|a| (0..n).map(|x| ((a * x) % n) as u16).collect())
        .collect();
    Group::new(format!("units({})", n), n, gens)
}

/// group("Q8"), group("V4") and friends
pub fn named(s: &str) -> Result<Group, String> {
    let p = |v: &[u16]| -> Perm { v.iter().map(|k| k - 1).collect() };
    match s.trim().to_lowercase().as_str() {
        // quaternions acting on themselves: 1 i j k -1 -i -j -k = points 1..8
        "q8" | "quaternion" => Group::new(
            "group(\"Q8\")",
            8,
            vec![
                p(&[2, 5, 4, 7, 6, 1, 8, 3]), // left multiplication by i
                p(&[3, 8, 5, 2, 7, 4, 1, 6]), // by j
            ],
        ),
        "v4" | "klein" => Group::new("group(\"V4\")", 4, vec![p(&[2, 1, 4, 3]), p(&[3, 4, 1, 2])]),
        "trivial" | "1" => Group::new("group(\"trivial\")", 1, vec![]),
        _ => Err(format!(
            "group(\"{}\"): known names are Q8 (quaternion group), V4 (Klein four-group) and trivial; or give generating permutations, group([2, 1, 3], [2, 3, 1])",
            s
        )),
    }
}

// ---------- homomorphisms ----------

/// The map G -> H sending G's generators to `images` (elements of H), when it is a
/// homomorphism: pairs (g, f(g)) for every g, in the order of G's elements
pub fn hom_table(g: &Group, h: &Group, images: &[Perm]) -> Result<Vec<Perm>, String> {
    if images.len() != g.gens.len() {
        return Err(format!(
            "give one image for each of the {} generators of {} ({})",
            g.gens.len(),
            g.name,
            g.gens.iter().map(show_perm).collect::<Vec<_>>().join(", ")
        ));
    }
    let mut map: Vec<Option<Perm>> = vec![None; g.order()];
    let id = g.identity();
    map[g.index[&id]] = Some(h.identity());
    let mut todo = vec![id];
    while let Some(x) = todo.pop() {
        let fx = map[g.index[&x]].clone().unwrap();
        for (s, t) in g.gens.iter().zip(images) {
            let y = mul(s, &x);
            let fy = mul(t, &fx);
            let j = g.index[&y];
            match &map[j] {
                None => {
                    map[j] = Some(fy);
                    todo.push(y);
                }
                Some(old) if *old != fy => {
                    return Err(format!(
                        "this is not a homomorphism: {} would have to go to both {} and {}",
                        show_perm(&y),
                        show_perm(old),
                        show_perm(&fy)
                    ));
                }
                _ => {}
            }
        }
    }
    Ok(map.into_iter().map(|m| m.unwrap()).collect())
}

pub fn kernel(g: &Group, h: &Group, images: &[Perm]) -> Result<Group, String> {
    let t = hom_table(g, h, images)?;
    let hid = h.identity();
    let k: Vec<Perm> = g
        .elems
        .iter()
        .zip(&t)
        .filter(|(_, f)| **f == hid)
        .map(|(x, _)| x.clone())
        .collect();
    g.sub(k)
}

pub fn image(g: &Group, h: &Group, images: &[Perm]) -> Result<Group, String> {
    hom_table(g, h, images)?;
    h.sub(images.to_vec())
}

/// a generating set of at most a few elements (greedy)
fn small_gens(g: &Group) -> Vec<Perm> {
    if g.gens.len() <= 2 {
        return g.gens.clone();
    }
    let mut gens: Vec<Perm> = vec![];
    let mut h = g.sub(vec![]).unwrap();
    // prefer elements of large order
    let mut cand: Vec<&Perm> = g.elems.iter().collect();
    cand.sort_by_key(|x| std::cmp::Reverse(order_of(x)));
    while h.order() < g.order() {
        let mut best: Option<(usize, Perm)> = None;
        for x in cand.iter().take(400) {
            if h.contains(x) {
                continue;
            }
            let mut gs = gens.clone();
            gs.push((*x).clone());
            let k = g.sub(gs).unwrap().order();
            if best.as_ref().is_none_or(|b| k > b.0) {
                best = Some((k, (*x).clone()));
            }
        }
        let Some((_, x)) = best else { break };
        gens.push(x);
        h = g.sub(gens.clone()).unwrap();
    }
    gens
}

/// numbers that two isomorphic groups share
fn invariants(g: &Group) -> (usize, Vec<(usize, usize)>, Vec<usize>, bool) {
    let mut cs: Vec<usize> = g.classes().iter().map(|c| c.len()).collect();
    cs.sort();
    (g.order(), g.order_counts(), cs, g.is_abelian())
}

/// an isomorphism G -> H as images of a small generating set of G, if there is one
pub fn isomorphism(g: &Group, h: &Group) -> Option<(Vec<Perm>, Vec<Perm>)> {
    if invariants(g) != invariants(h) {
        return None;
    }
    let gg = Group::new(g.name.clone(), g.degree, small_gens(g)).ok()?;
    let cands: Vec<Vec<&Perm>> = gg
        .gens
        .iter()
        .map(|s| {
            h.elems
                .iter()
                .filter(|y| order_of(y) == order_of(s))
                .collect()
        })
        .collect();
    let mut pick = vec![0usize; cands.len()];
    let mut tries = 0u64;
    loop {
        let imgs: Vec<Perm> = pick
            .iter()
            .zip(&cands)
            .map(|(&i, c)| c[i].clone())
            .collect();
        if let Ok(t) = hom_table(&gg, h, &imgs) {
            let mut seen = std::collections::HashSet::new();
            if t.iter().all(|y| seen.insert(y.clone())) {
                return Some((gg.gens.clone(), imgs));
            }
        }
        tries += 1;
        if tries > 2_000_000 {
            return None;
        }
        // next combination
        let mut k = 0;
        loop {
            if k == pick.len() {
                return None;
            }
            pick[k] += 1;
            if pick[k] < cands[k].len() {
                break;
            }
            pick[k] = 0;
            k += 1;
        }
    }
}

/// invariant factors d1 | d2 | ... of a finite abelian group (from counting
/// solutions of x^(p^k) = 1)
pub fn abelian_invariants(a: &Group) -> Vec<u64> {
    let n = a.order() as u64;
    let mut factors: Vec<u64> = vec![];
    let mut m = n;
    let mut p = 2u64;
    let mut parts: Vec<(u64, Vec<u32>)> = vec![];
    while m > 1 {
        if m % p == 0 {
            let mut e = 0;
            while m % p == 0 {
                m /= p;
                e += 1;
            }
            // c_k = log_p #{x : x^(p^k) = 1}; then the number of cyclic factors of
            // order >= p^k is c_k - c_(k-1)
            let mut c = vec![0u32];
            let mut pk = 1u64;
            for _ in 1..=e {
                pk *= p;
                let cnt = a
                    .elems
                    .iter()
                    .filter(|x| pk % order_of(x) as u64 == 0)
                    .count() as u64;
                let mut l = 0;
                let mut v = cnt;
                while v > 1 {
                    v /= p;
                    l += 1;
                }
                c.push(l);
            }
            // exponents of the cyclic factors, largest first
            let mut exps = vec![];
            for k in (1..=e as usize).rev() {
                let at_least = c[k] - c[k - 1];
                let at_least_next = if k < e as usize { c[k + 1] - c[k] } else { 0 };
                for _ in 0..(at_least - at_least_next) {
                    exps.push(k as u32);
                }
            }
            parts.push((p, exps));
        }
        p += 1;
    }
    let len = parts.iter().map(|(_, e)| e.len()).max().unwrap_or(0);
    for i in 0..len {
        let mut d = 1u64;
        for (p, e) in &parts {
            if let Some(&k) = e.get(i) {
                d *= p.pow(k);
            }
        }
        factors.push(d);
    }
    factors.reverse();
    factors
}

// ---------- presentations ----------

/// A word in the generators: (generator index, exponent ±1)
type Word = Vec<(usize, i32)>;

fn parse_word(s: &str, names: &[String]) -> Result<Word, String> {
    // a product of factors name, name^k, (word)^k
    fn factor(t: &[char], i: &mut usize, names: &[String]) -> Result<Word, String> {
        while *i < t.len() && t[*i] == ' ' {
            *i += 1;
        }
        let base: Word = if *i < t.len() && t[*i] == '(' {
            *i += 1;
            let w = product(t, i, names)?;
            if *i >= t.len() || t[*i] != ')' {
                return Err("missing )".into());
            }
            *i += 1;
            w
        } else {
            let start = *i;
            while *i < t.len() && (t[*i].is_alphanumeric() || t[*i] == '_') {
                *i += 1;
            }
            let nm: String = t[start..*i].iter().collect();
            if nm == "1" {
                vec![]
            } else {
                let k = names
                    .iter()
                    .position(|n| *n == nm)
                    .ok_or_else(|| format!("unknown generator '{}'", nm))?;
                vec![(k, 1)]
            }
        };
        while *i < t.len() && t[*i] == ' ' {
            *i += 1;
        }
        if *i < t.len() && t[*i] == '^' {
            *i += 1;
            let neg = *i < t.len() && t[*i] == '-';
            if neg {
                *i += 1;
            }
            let start = *i;
            while *i < t.len() && t[*i].is_ascii_digit() {
                *i += 1;
            }
            let k: i32 = t[start..*i]
                .iter()
                .collect::<String>()
                .parse()
                .map_err(|_| "bad exponent".to_string())?;
            let unit: Word = if neg {
                base.iter().rev().map(|&(g, e)| (g, -e)).collect()
            } else {
                base
            };
            Ok((0..k).flat_map(|_| unit.clone()).collect())
        } else {
            Ok(base)
        }
    }
    fn product(t: &[char], i: &mut usize, names: &[String]) -> Result<Word, String> {
        let mut w = factor(t, i, names)?;
        loop {
            while *i < t.len() && t[*i] == ' ' {
                *i += 1;
            }
            if *i < t.len() && t[*i] == '*' {
                *i += 1;
                w.extend(factor(t, i, names)?);
            } else {
                return Ok(w);
            }
        }
    }
    let t: Vec<char> = s.chars().collect();
    let mut i = 0;
    let w = product(&t, &mut i, names)?;
    if i != t.len() {
        return Err(format!("could not read '{}'", s));
    }
    Ok(w)
}

/// The group <gens | relators> by Todd–Coxeter coset enumeration (HLT), as the
/// permutations of the cosets of the trivial subgroup
pub fn presentation(text: &str) -> Result<Group, String> {
    const MAX: usize = 60_000;
    let inner = text.trim().trim_start_matches('<').trim_end_matches('>');
    let (g, r) = inner
        .split_once('|')
        .ok_or("a presentation looks like <a, b | a^4, b^2, (a*b)^2>")?;
    let names: Vec<String> = g
        .split(',')
        .map(|s| s.trim().to_string())
        .filter(|s| !s.is_empty())
        .collect();
    if names.is_empty() {
        return Err("no generators".into());
    }
    let rels: Vec<Word> = r
        .split(',')
        .map(|s| s.trim())
        .filter(|s| !s.is_empty())
        .map(|s| parse_word(s, &names))
        .collect::<Result<_, _>>()?;
    let ng = names.len();
    // columns: 2k = generator k, 2k+1 = its inverse
    let col = |(g, e): (usize, i32)| if e > 0 { 2 * g } else { 2 * g + 1 };
    let inv_col = |c: usize| c ^ 1;
    let mut table: Vec<Vec<usize>> = vec![vec![usize::MAX; 2 * ng]];
    let mut parent: Vec<usize> = vec![0]; // union-find for coincidences
    fn find(p: &mut [usize], x: usize) -> usize {
        let mut r = x;
        while p[r] != r {
            r = p[r];
        }
        let mut x = x;
        while p[x] != r {
            let n = p[x];
            p[x] = r;
            x = n;
        }
        r
    }
    let mut c = 0;
    while c < table.len() {
        if find(&mut parent, c) != c {
            c += 1;
            continue;
        }
        for rel in &rels {
            if find(&mut parent, c) != c {
                break;
            }
            // trace rel from c, defining new cosets as needed (HLT)
            let mut x = c;
            for (k, &l) in rel.iter().enumerate() {
                let cc = col(l);
                x = find(&mut parent, x);
                let y = table[x][cc];
                if y != usize::MAX && k + 1 < rel.len() {
                    x = find(&mut parent, y);
                    continue;
                }
                if k + 1 == rel.len() {
                    // the last letter must bring x back to c
                    let cc0 = find(&mut parent, c);
                    if y == usize::MAX {
                        table[x][cc] = cc0;
                        if table[cc0][inv_col(cc)] == usize::MAX {
                            table[cc0][inv_col(cc)] = x;
                        } else if find(&mut parent, table[cc0][inv_col(cc)]) != x {
                            let z = table[cc0][inv_col(cc)];
                            coincide(&mut table, &mut parent, z, x);
                        }
                    } else if find(&mut parent, y) != cc0 {
                        coincide(&mut table, &mut parent, y, cc0);
                    }
                    break;
                }
                if table.len() >= MAX {
                    return Err(format!(
                        "coset enumeration passed {} cosets: the group is infinite or too large",
                        MAX
                    ));
                }
                let n = table.len();
                table.push(vec![usize::MAX; 2 * ng]);
                parent.push(n);
                table[x][cc] = n;
                table[n][inv_col(cc)] = x;
                x = n;
            }
        }
        // make sure every entry of row c is defined
        if find(&mut parent, c) == c {
            for cc in 0..2 * ng {
                if table[c][cc] == usize::MAX {
                    if table.len() >= MAX {
                        return Err(format!(
                            "coset enumeration passed {} cosets: the group is infinite or too large",
                            MAX
                        ));
                    }
                    let n = table.len();
                    table.push(vec![usize::MAX; 2 * ng]);
                    parent.push(n);
                    table[c][cc] = n;
                    table[n][inv_col(cc)] = c;
                }
            }
        }
        c += 1;
    }
    // live cosets, renumbered
    let live: Vec<usize> = (0..table.len())
        .filter(|&x| find(&mut parent, x) == x)
        .collect();
    let pos: HashMap<usize, usize> = live.iter().enumerate().map(|(i, &x)| (x, i)).collect();
    let n = live.len();
    if n > u16::MAX as usize {
        return Err("the group is too large".into());
    }
    let mut gens = vec![];
    for k in 0..ng {
        let mut p = vec![0u16; n];
        for (i, &x) in live.iter().enumerate() {
            let y = find(&mut parent, table[x][2 * k]);
            p[i] = pos[&y] as u16;
        }
        gens.push(p);
    }
    Group::new(format!("group(\"{}\")", text.trim()), n, gens)
}

/// merge cosets a and b and everything that follows from it
fn coincide(table: &mut [Vec<usize>], parent: &mut [usize], a: usize, b: usize) {
    fn find(p: &mut [usize], x: usize) -> usize {
        let mut r = x;
        while p[r] != r {
            r = p[r];
        }
        r
    }
    let mut queue = vec![(a, b)];
    while let Some((a, b)) = queue.pop() {
        let (a, b) = (find(parent, a), find(parent, b));
        if a == b {
            continue;
        }
        let (keep, gone) = if a < b { (a, b) } else { (b, a) };
        parent[gone] = keep;
        for cc in 0..table[gone].len() {
            let y = table[gone][cc];
            if y == usize::MAX {
                continue;
            }
            let k = table[keep][cc];
            if k == usize::MAX {
                table[keep][cc] = y;
            } else {
                queue.push((k, y));
            }
            // fix the back edge
            let yy = find(parent, y);
            let ic = cc ^ 1;
            if table[yy][ic] == gone || table[yy][ic] == usize::MAX {
                table[yy][ic] = keep;
            } else if find(parent, table[yy][ic]) != keep {
                queue.push((table[yy][ic], keep));
            }
        }
    }
}
